     reflow the line. At 10-11px it is what makes the accent legal (`DESIGN_SPEC` §6). */
  .handle {
    font-weight: 500;
  }

  .handle:hover {
    color: var(--color-accent);
  }

  .sig {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .glyph {
    color: var(--color-accent);
    font-weight: 500;
    text-shadow: 0 0 10px var(--color-accent);
