        color-mix(in srgb, var(--color-accent) 45%, transparent)
      );
  }

  .sub {
    max-width: 480px;
  }

  .ctas {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 6px;
  }

  .cta {
    padding: 14px 22px;
    border-radius: 999px;
    font-size: 15px;
    font-weight: 500;
    transition: border-color 0.2s;
  }

  .primary {
    background: var(--color-ink);
    color: var(--color-bg);
  }

  .secondary {
    border: 1px solid color-mix(in srgb, var(--color-ink) 14%, transparent);
    color: var(--color-ink);
  }

  .secondary:hover {
    border-color: var(--color-accent);
  }

  .stats {
    display: flex;
    flex-wrap: wrap;
    gap: 12px 24px;
    margin-top: 10px;
    font-size: var(--text-label);
    white-space: nowrap;
    color: var(--color-dim);
  }

  .stats b {
    color: var(--color-ink);
    font-weight: 500;
  }

  @media (prefers-reduced-motion: no-preference) {
    .cursor {
      animation: blink 1s steps(1) infinite;
    }

    /* The lift of `DESIGN_SPEC` §4 is motion like any other: with `reduce` the button
       still takes its hover border, it just does not move. */
    .cta {
      transition:
        transform 0.2s,
        border-color 0.2s;
    }

    .primary:hover {
      transform: translateY(-1px);
    }
  }
</style>

<script>
  import { boot } from '../lib/motion/boot'
  import { typedLength } from '../lib/motion/math'
  import { mountNetwork } from '../lib/motion/network'
  import { prefersReducedMotion } from '../lib/motion/reduced'

  boot()

  // The canvas is a direct child of the full-bleed shell and is measured against the
  // console card. `mountNetwork` creates nothing with `prefers-reduced-motion: reduce`.
  const hero = document.querySelector<HTMLElement>('.hero')
  const card = document.querySelector<HTMLElement>('[data-console]')
  if (hero && card) mountNetwork(hero, card)

  const eyebrow = document.querySelector<HTMLElement>('[data-typed]')
  if (eyebrow && !prefersReducedMotion()) {
    const text = eyebrow.textContent ?? ''
    eyebrow.textContent = ''

    // rAF, not an interval: the 700ms wait is an offset on the elapsed time, so the
    // typing stays in step with the boot transitions instead of drifting past them.
    let start: number | undefined
    const step = (now: number) => {
      start ??= now
      const n = typedLength(now - start - 700, 28, text.length)
      eyebrow.textContent = text.slice(0, n)
      if (n < text.length) requestAnimationFrame(step)
    }
    requestAnimationFrame(step)
  }
</script>

